package com.payshield.service; import org.springframework.stereotype.Component; @Component public class MockGateway { public GatewayResult charge(String token){return switch(token){case "tok_visa_success" -> GatewayResult.success();case "tok_declined" -> GatewayResult.declined();case "tok_gateway_error" -> GatewayResult.error();default -> GatewayResult.declined();};} public record GatewayResult(boolean succeeded,String reason){static GatewayResult success(){return new GatewayResult(true,null);} static GatewayResult declined(){return new GatewayResult(false,"Card declined by simulated gateway");} static GatewayResult error(){return new GatewayResult(false,"Simulated retryable gateway error");}} }
